// Rules: days after the quote date / after the invoice due date, from Settings.
// Only rows with status "open" are handled. Change any other status (paid, won, lost) to stop.
const DAY_MS = 86400000;

function parseDays(s, fallback) {
  const d = String(s ?? '').split(',').map((x) => parseInt(x, 10)).filter((n) => n >= 0);
  return d.length ? d.sort((a, b) => a - b) : fallback;
}

function isoDay(s) {
  if (typeof s === 'number') return s > 0 ? Math.round((Math.floor(s) - 25569) * 86400000) : null;
  const m =/^(\d{4})-(\d{2})-(\d{2})$/.exec(String(s ?? '').trim());
  if (!m) return null;
  const t = Date.UTC(+m[1], +m[2] - 1, +m[3]);
  return new Date(t).getUTCDate() === +m[3] ? t : null; // rejects 2026-02-30
}

function message(type, stage, total, r, days, cfg) {
  const hi = `Hi ${r.client_name || 'there'},`;
  const bye = `\n\nBest regards,\n${cfg.your_name}${cfg.your_company ? `\n${cfg.your_company}` : ''}`;
  const last = stage === total;
  if (type === 'quote') {
    if (stage === 1) return [`Quick check on quote ${r.number}`, `${hi}\n\nI sent you quote ${r.number} (${r.amount}) on ${r.date}. Did you have a chance to look at it? I'm happy to answer any questions.${bye}`];
    if (!last) return [`Any questions about quote ${r.number}?`, `${hi}\n\nI'm following up on quote ${r.number} (${r.amount}). If anything is unclear or you'd like a change, just reply to this email.${bye}`];
    return [`Should I close quote ${r.number}?`, `${hi}\n\nI haven't heard back about quote ${r.number} (${r.amount}). If now isn't the right time, no problem: reply and I'll close it on my side. If you'd like to go ahead, a short "yes" is enough.${bye}`];
  }
  const pay = cfg.payment_details ? `\n\nPayment details: ${cfg.payment_details}` : '';
  const paid = '\n\nIf you have already paid, please ignore this email.';
  if (stage === 1) return [`Friendly reminder: invoice ${r.number}`, `${hi}\n\nInvoice ${r.number} (${r.amount}) was due on ${r.date}. In case it slipped through, here is a quick reminder.${pay}${paid}${bye}`];
  if (!last) return [`Second reminder: invoice ${r.number} is ${days} days overdue`, `${hi}\n\nInvoice ${r.number} (${r.amount}) is now ${days} days overdue. Could you let me know when I can expect payment?${pay}${paid}${bye}`];
  return [`Final reminder: invoice ${r.number}`, `${hi}\n\nInvoice ${r.number} (${r.amount}) is ${days} days overdue. Please arrange payment within 7 days, or reply if there is a problem with the invoice.${pay}${paid}${bye}`];
}

function plan(rows, cfg, today) {
  const now = isoDay(today);
  const ladders = { quote: parseDays(cfg.quote_days, [3, 7, 14]), invoice: parseDays(cfg.invoice_days, [3, 10, 21]) };
  const callAfter = parseInt(cfg.call_after_days, 10) >= 0 ? parseInt(cfg.call_after_days, 10) : 7;
  const dry = cfg.dry_run === true || String(cfg.dry_run).toLowerCase() === 'true';
  const out = [];
  for (const r of rows) {
    if (String(r.status ?? '').trim().toLowerCase() !== 'open') continue; // paid, won, lost, empty row: stop
    const base = { row_number: r.row_number, type: String(r.type ?? '').trim().toLowerCase(), number: r.number, client_name: r.client_name, client_email: String(r.client_email ?? '').trim(), dry_run: dry };
    const steps = ladders[base.type];
    const start = isoDay(r.date);
    const problem = !steps ? 'type must be "quote" or "invoice"'
      : start === null ? 'date must be a date cell or YYYY-MM-DD text'
      : !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(base.client_email) ? 'client_email is missing or invalid'
      : null;
    if (problem) { out.push({ ...base, action: 'attention', reason: problem }); continue; }
    const days = Math.floor((now - start) / DAY_MS);
    const sent = Math.max(0, parseInt(r.last_stage, 10) || 0);
    const due = steps.filter((d) => days >= d).length;
    if (due > sent) {
      // Only the highest due stage goes out, so a late start never sends several emails at once.
      const [subject, body] = message(base.type, due, steps.length, { ...r, date: new Date(start).toISOString().slice(0, 10) }, days, cfg);
      out.push({ ...base, action: 'email', new_stage: due, days,
        to: dry ? cfg.owner_email : base.client_email,
        subject: dry ? `[TEST for ${base.client_email}] ${subject}` : subject, body });
    } else if (sent >= steps.length && days >= steps[steps.length - 1] + callAfter) {
      out.push({ ...base, action: 'call', days, reason: base.type === 'quote' ? 'no answer after the last follow-up' : 'still unpaid after the final reminder' });
    }
  }
  return out;
}

const cfg = $('Settings').first().json;
return plan($input.all().map((i) => i.json), cfg, $now.toISODate()).map((json) => ({ json }));

// Runs after the email branch (it sits lower on the canvas; n8n runs branches top to bottom).
function summarize(planned, sent, failed, cfg, today) {
  const line = (x) => `- ${x.type} ${x.number}, ${x.client_name || x.client_email}`;
  const calls = planned.filter((x) => x.action === 'call');
  const fix = planned.filter((x) => x.action === 'attention');
  const dry = cfg.dry_run === true || String(cfg.dry_run).toLowerCase() === 'true';
  const parts = [`Follow-up run ${today}${dry ? ' (TEST MODE: all emails went to you, the sheet was not updated)' : ''}.`];
  parts.push(`\nSent (${sent.length}):\n${sent.map((x) => `${line(x)} (stage ${x.new_stage})`).join('\n') || '- none due today'}`);
  if (failed.length) parts.push(`\nFailed, will retry tomorrow (${failed.length}):\n${failed.map((x) => `${line(x)}: ${x.error}`).join('\n')}`);
  if (calls.length) parts.push(`\nCall these clients (${calls.length}):\n${calls.map((x) => `${line(x)}, ${x.days} days, ${x.reason}`).join('\n')}`);
  if (fix.length) parts.push(`\nFix in the sheet, skipped (${fix.length}):\n${fix.map((x) => `- row ${x.row_number}: ${x.reason}`).join('\n')}`);
  return {
    to: cfg.owner_email,
    subject: `${dry ? '[TEST] ' : ''}Follow-ups ${today}: ${sent.length} sent, ${failed.length} failed, ${calls.length} to call, ${fix.length} to fix`,
    body: parts.join('\n'),
  };
}

const cfg = $('Settings').first().json;
// If you rename these nodes, rename them here too. A wrong name stops the run with an error instead of reporting 0.
const all = (node) => ($(node).isExecuted ? $(node).all().map((i) => i.json) : []); // [] = node didn't run today
return [{ json: summarize(all('Plan follow-ups'), all('Mark as sent'), all('Mark as failed'), cfg, $now.toISODate()) }];
